<?php
declare(strict_types=1);
define('XAR_SPECIAL_FIXTURE_ONLY',true);require __DIR__.'/tactical-special-effects.php';$specialChecks=0;
function superFixture():MemoryConnection {
 $db=specialFixture();$c=$db->payload('character:character-player');$c['resources']=['hp'=>20,'maxHp'=>300,'mana'=>100,'maxMana'=>100];
 $c['passiveAbilities']=[['version'=>1,'id'=>'mania-ability-fatigue','kind'=>'ability-fatigue-surcharge','amount'=>1]];
 $c['abilities']=[['id'=>'super-test','name'=>'Préparation libre','effect'=>'enhancement','formula'=>'0','castingStatId'=>'','manaCost'=>30,'fatigueCost'=>10,'fatigueCostIncludesPassive'=>false,'restRecharge'=>'long','usesPerRest'=>1,'attackEnhancement'=>['mode'=>'next-item-use','itemKind'=>'potion','multipliers'=>['healing'=>2,'damage'=>2,'area'=>2,'duration'=>2],'turns'=>1,'target'=>'self','expiry'=>'combat-or-rest']]];
 $db->put('character:character-player',$c);$source=synchronizeOnlineCharacterToken($db->payload('token:scene-one:token-player'),$c);$db->put('token:scene-one:token-player',$source);return $db;
