function superCommand(MemoryConnection $db,string $command,array $args=[],bool $gm=true):TestResponse {return runCommand($db,$command,['requestId'=>'super-'.randomToken(18),'sceneId'=>'scene-one','characterId'=>'character-player','tokenId'=>'token-player',...$args],$gm,$gm?'account-gm':'account-player');}
function superCast(MemoryConnection $db,array $extra=[]):TestResponse {return superCommand($db,'ability.use',['sourceTokenId'=>'token-player','targetTokenId'=>'token-player','abilityId'=>'super-test',...$extra],false);}
function superGive(MemoryConnection $db,array $template,string $itemId):void {
 specialCheck(superCommand($db,'item.template.create',['template'=>$template])->status===200,'Create synthetic potion');specialCheck(superCommand($db,'item.spawn',['itemId'=>$itemId,'templateId'=>$template['id'],'location'=>['kind'=>'inventory','characterId'=>'character-player']])->status===200,'Give existing test potion');
}
$db=superFixture();$castArgs=['requestId'=>'super-cast-fixed'];$r=superCast($db,$castArgs);specialCheck($r->status===200&&!empty($r->body['castSucceeded']),'Native activation: '.json_encode($r->body));specialCheck(superCast($db,$castArgs)->body['deduplicated']===true,'Cast replay');
specialCheck($db->payload('character:character-player')['resources']['mana']===70,'Thirty mana paid once');specialCheck($db->payload('character:character-player')['fatigue']['current']===11,'Inclusive eleven fatigue, surcharge not paid twice');
$prepared=$db->payload('activity')['attackEnhancements'];specialCheck(count($prepared)===1&&$prepared[0]['mode']==='next-item-use','One preparation');
superGive($db,['id'=>'flat-test','name'=>'Potion fictive','kind'=>'potion','potion'=>['hp'=>10,'mana'=>0,'fatigue'=>0]],'test-bottle');
$args=['requestId'=>'super-drink-fixed','itemId'=>'test-bottle','expectedItemRevision'=>1,'expectedItemEnhancementId'=>$prepared[0]['id']];$r=superCommand($db,'item.consume',$args,false);specialCheck($r->status===200,'Native empowered drink: '.json_encode($r->body));specialCheck(superCommand($db,'item.consume',$args,false)->body['deduplicated']===true,'Potion replay');
specialCheck($db->payload('character:character-player')['resources']['hp']===40,'Healing doubled once');specialCheck($db->payload('activity')['attackEnhancements']===[],'Preparation consumed');
$action=null;foreach($db->payload('activity')['combatActions'] as $candidate)if(in_array('request:super-drink-fixed',$candidate['aliases'],true))$action=$candidate;
specialCheck($action!==null&&!empty($action['actionIds']),'Potion linked to GM action recap');$r=superCommand($db,'action.undo',['actionId'=>$action['actionIds'][0]]);specialCheck($r->status===200,'Native undo: '.json_encode($r->body));
specialCheck($db->payload('character:character-player')['resources']['hp']===20,'Undo healing');specialCheck($db->payload('items')['instances'][0]['location']['kind']==='inventory','Undo restores bottle');specialCheck($db->payload('activity')['attackEnhancements']===$prepared,'Undo restores same preparation');specialCheck($db->payload('character:character-player')['resources']['mana']===70,'Undo potion does not undo original casting cost');
superCommand($db,'item.effects.rest',['unitIds'=>['character-player'],'kind'=>'short']);specialCheck(count($db->payload('activity')['attackEnhancements'])===0,'Short rest clears preparation');
$effects=applicationAdvanceAttackEnhancements($prepared,'scene-one',['active'=>true,'combatId'=>'special-test'],['active'=>false]);specialCheck($effects===[],'Combat ending clears preparation');$effects=applicationAdvanceAttackEnhancements($prepared,'scene-one',[],[],true);specialCheck($effects===$prepared,'Manual turn preserves preparation');
$activity=$db->payload('activity');$activity['attackEnhancements']=$prepared;$db->put('activity',$activity);superCommand($db,'item.effects.rest',['unitIds'=>['character-player'],'kind'=>'long']);specialCheck($db->payload('activity')['attackEnhancements']===[],'Long rest clears preparation');
$db=superFixture();specialCheck(superCast($db)->status===200,'Area preparation');$target=$db->payload('token:scene-one:token-monster');$target['id']='second-guard';$target['name']='Garde';$target['x']=59;$db->put('token:scene-one:second-guard',$target);$target['id']='outside';$target['x']=90;$db->put('token:scene-one:outside',$target);$index=$db->payload('token-index:scene-one');$index['order']=[...$index['order'],'second-guard','outside'];$db->put('token-index:scene-one',$index);
superGive($db,['id'=>'area-test','name'=>'Potion de zone','kind'=>'potion','potion'=>['hp'=>0,'mana'=>0,'fatigue'=>0],'active'=>['version'=>1,'authority'=>'owner','useLabel'=>'Lancer','targeting'=>['mode'=>'area','origin'=>'point','rangeCells'=>15,'radiusCells'=>1],'effects'=>[['kind'=>'damage','components'=>[['type'=>'ignore','formula'=>'5']]]]]],'area-bottle');
$args=['itemId'=>'area-bottle','expectedItemRevision'=>1,'targetPoint'=>['x'=>50,'y'=>50],'opposed'=>false];$r=superCommand($db,'item.activate',$args,false);specialCheck($r->status===200,'Native area launch: '.json_encode($r->body));$use=$db->payload('items')['pendingUses'][0];specialCheck($use['phase']==='defense-selection','Player cannot select no opposition for area');specialCheck(in_array('second-guard',array_column($use['targets'],'tokenId'),true),'Enlarged radius includes second guard: '.json_encode($use));specialCheck(!in_array('outside',array_column($use['targets'],'tokenId'),true),'Outside guard excluded');
specialCheck(superCommand($db,'item.defenses.select',['useId'=>$use['id'],'targetTokenIds'=>[]],false)->status===403,'Defense choice belongs to GM');specialCheck(superCommand($db,'item.defenses.select',['useId'=>$use['id'],'targetTokenIds'=>['outside']])->status===409,'Cannot select unrelated token');
specialCheck(superCommand($db,'item.use.cancel',['useId'=>$use['id']])->status===200,'Cancel area');specialCheck(count($db->payload('activity')['attackEnhancements'])===1&&$db->payload('items')['instances'][0]['location']['kind']==='inventory','Cancellation preserves preparation and potion');
$r=superCommand($db,'item.activate',$args,false);$use=$db->payload('items')['pendingUses'][0];$r=superCommand($db,'item.defenses.select',['useId'=>$use['id'],'targetTokenIds'=>[]]);specialCheck($r->status===200,'GM confirms no defenses: '.json_encode($r->body));specialCheck($db->payload('token:scene-one:token-monster')['hp']===490,'Area damage doubled');specialCheck($db->payload('token:scene-one:second-guard')['hp']===490,'All affected recipients share same preparation');specialCheck($db->payload('token:scene-one:outside')['hp']===500,'Unrelated unit unchanged');specialCheck($db->payload('activity')['attackEnhancements']===[],'Area consumes preparation once');
fwrite(STDOUT,json_encode(['ok'=>true,'checks'=>$specialChecks],JSON_UNESCAPED_UNICODE)."\n");
